<?php
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/CharacterAutomationService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once $root.'/app/LobbyService.php';AuthService::boot();$user=AuthService::requireLogin();$gid=(int)($_GET['game']??$_POST['game_id']??0);if($gid<1){header('Location: ./');exit;}
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');if($action==='claim')LobbyService::claimCharacter($gid,(int)$user['user_id'],(int)$_POST['character_id']);if($action==='release')LobbyService::releaseCharacter($gid,(int)$user['user_id']);if($action==='invite_player'){$invite=AuthService::createGameInvitation((string)$_POST['email'],$gid,(int)$user['user_id']);$_SESSION['lobby_notice']=$invite['sent']?'Invitation sent from newsletter@sixpillarsmodel.com.':'Email delivery was unavailable. Share this secure link: '.$invite['url'];}if($action==='start')LobbyService::startGame($gid,(int)$user['user_id']);header('Location: '.($action==='start'?'play.php':'lobby.php').'?game='.$gid);exit;}catch(Throwable$e){$error=$e->getMessage();}}
try{$state=LobbyService::lobbyState($gid,(int)$user['user_id']);}catch(Throwable$e){http_response_code(403);die(e($e->getMessage()));}if($state['game']['status']!=='LOBBY'){header('Location: play.php?game='.$gid);exit;}
function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
function lobby_duration(int $seconds):string{if($seconds%86400===0)return intdiv($seconds,86400).' '.(intdiv($seconds,86400)===1?'Day':'Days');if($seconds%60===0)return intdiv($seconds,60).' Minutes';return$seconds.' Seconds';}
$mine=null;foreach($state['players']as$p)if((int)$p['user_id']===(int)$user['user_id'])$mine=(int)($p['character_id']??0);$notice=(string)($_SESSION['lobby_notice']??'');unset($_SESSION['lobby_notice']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Game Lobby · Toinky</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#eef2f7}*{box-sizing:border-box}body{margin:0}.bar{background:#111827;color:#fff;padding:15px 22px}.barin,.shell{max-width:1100px;margin:auto}.barin{display:flex;justify-content:space-between;align-items:center}.bar a{color:#fff}.shell{padding:28px 20px}.top,.players{display:flex;gap:16px;justify-content:space-between;align-items:center;flex-wrap:wrap}.code{font:900 34px ui-monospace,monospace;letter-spacing:.18em;background:#fff;border:2px dashed #818cf8;border-radius:13px;padding:12px 18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:15px;margin-top:18px}.card{background:#fff;border:2px solid #dce3ec;border-radius:15px;padding:18px}.card.taken{opacity:.48;filter:grayscale(.55)}.card.mine{border-color:#4f46e5;box-shadow:0 0 0 3px #c7d2fe}.btn{border:0;border-radius:9px;background:#4f46e5;color:#fff;padding:10px 14px;font:inherit;font-weight:800;cursor:pointer}.btn.alt{background:#fff;color:#273043;border:1px solid #cbd5e1}.btn.start{background:#059669;font-size:17px;padding:13px 20px}.error{background:#fee2e2;color:#991b1b;padding:12px;border-radius:10px;margin-bottom:15px}.muted{color:#64748b}.people{background:#fff;border-radius:13px;padding:16px;margin:20px 0}.person{display:inline-block;margin:5px 8px 5px 0;padding:7px 10px;background:#f1f5f9;border-radius:8px}
</style></head><body><header class="bar"><div class="barin"><b>Toinky Lobby</b><a href="./">Leave lobby</a></div></header><main class="shell"><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="people"><?=e($notice)?></div><?php endif;?><div class="top"><div><h1><?=e($state['game']['title'])?></h1><p class="muted"><?=e($state['game']['genre'])?> · Hosted by <?=e($state['game']['host_name'])?> · <?=e(lobby_duration((int)($state['game']['play_duration_seconds']??$state['game']['duration_seconds'])))?></p><p>Share this code with the other players:</p></div><div class="code"><?=e($state['game']['join_code'])?></div></div>
<section class="people"><b>Players in Lobby</b><div><?php foreach($state['players']as$p):?><span class="person"><?=e($p['display_name'])?><?=empty($p['character_id'])?' · choosing…':' · ready'?></span><?php endforeach;?></div></section>
<h2>Choose Your Character</h2><p class="muted">A claimed character becomes unavailable to everyone else within a few seconds. Every unclaimed character will be controlled by AI.</p><div class="grid"><?php foreach($state['characters']as$c):$taken=!empty($c['user_id'])&&(int)$c['user_id']!==(int)$user['user_id'];$isMine=(int)($c['user_id']??0)===(int)$user['user_id'];?><article class="card <?=$taken?'taken':''?> <?=$isMine?'mine':''?>"><h3><?=e($c['name'])?></h3><p><?=e($c['description'])?></p><?php if($taken):?><b>Chosen by <?=e($c['player_name'])?></b><?php elseif($isMine):?><b>Your Character</b><form method="post" style="margin-top:10px"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="release"><button class="btn alt">Choose Someone Else</button></form><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="claim"><input type="hidden" name="character_id" value="<?=(int)$c['character_id']?>"><button class="btn">Choose <?=e($c['name'])?></button></form><?php endif;?></article><?php endforeach;?></div>
<?php if($state['is_host']):?><section class="people"><h2>Invite Players by Email</h2><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="invite_player"><label>Email address <input type="email" name="email" required style="padding:10px;border:1px solid #cbd5e1;border-radius:8px"></label> <button class="btn">Send Invitation</button></form></section><section class="people"><h2>Host Controls</h2><p>Start once every joined player has chosen a character.</p><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="start"><button class="btn start">Start the Game</button></form></section><?php else:?><section class="people"><b>Waiting for the host to start…</b></section><?php endif;?></main>
<script>let fingerprint=<?=json_encode([$state['game']['status'],array_map(fn($p)=>[(int)$p['user_id'],(int)($p['character_id']??0)],$state['players'])])?>;setInterval(async()=>{try{const r=await fetch('lobby-state.php?game=<?=$gid?>',{cache:'no-store'});if(!r.ok)return;const s=await r.json();if(s.status!=='LOBBY'){location.href='play.php?game=<?=$gid?>';return;}if(JSON.stringify(s.fingerprint)!==JSON.stringify(fingerprint))location.reload();}catch(e){}},2000);</script></body></html>
